from lib import *
S = SS('l69')
steps = [
    step("同一个键 user.name 在 system、global、local 三个文件里各设一个值(系统层、全局层、仓库层)。git config --show-origin --show-scope --get-all user.name 按读取顺序列出:system(file:…/system.conf)→ global(…/global.conf)→ local(file:.git/config),git config user.name 取到最后一个“仓库层”。越靠后越优先:读取顺序是 system → global → local,后读的覆盖先读的。", t=tl(S(1)), mark=lidx(S(1), 'local\tfile:.git/config\t仓库层', '$ git config user.name'), done=lidx(S(1), 'system', 'global', '(--get-all 按读取顺序'), b=bars([['system', 1, '系统层'], ['global', 2, '全局层'], ['local', 3, '仓库层(生效)']], 3, mark=[2], done=[0, 1]), kv=KV([['system', '/etc/gitconfig 之类,最低'], ['global', '~/.gitconfig'], ['local', '.git/config,生效'], ['规则', '后读的覆盖先读的']], ['规则'])),
    step("命令行和环境变量还要更高:git -c user.name=命令行 config user.name 得到“命令行”;设 GIT_CONFIG_COUNT=1、GIT_CONFIG_KEY_0=user.name、GIT_CONFIG_VALUE_0=环境变量 得到“环境变量”。两者同时存在时 --show-scope --get-all 依次列出 system、global、local、command(环境变量)、command(命令行)——命令行 -c 在环境变量之后读,最后生效。", t=tl(S(2)), mark=lidx(S(2), 'command\t命令行', 'command\t环境变量'), done=lidx(S(2), '命令行', '环境变量'), kv=KV([['-c key=value', '最高'], ['GIT_CONFIG_COUNT / KEY_n / VALUE_n', '次之'], ['都是 command 层', '不属于任何文件']], ['-c key=value'])),
    step("worktree 层:设置 extensions.worktreeConfig = true 并 git config --worktree user.name 工作树层 之后,在那个附加工作树里 --show-scope --show-origin --get-all 多出一行 worktree(file:…/.git/worktrees/l69wt/config.worktree),排在 local 之后,所以生效值是“工作树层”;而主工作树里读不到这一层,仍然是“仓库层”。同一个仓库的不同工作树因此可以有不同的 user.name、core.sparseCheckout 等。", t=tl(S(3)), mark=lidx(S(3), 'worktree\tfile:/work/l69/.git/worktrees/l69wt/config.worktree'), done=lidx(S(3), '同一个仓库的另一个工作树'), kv=KV([['extensions.worktreeConfig', '打开 per-worktree 配置'], ['config.worktree', '在 .git/worktrees/<名>/'], ['优先级', '高于 local']], ['config.worktree'])),
    step("include 把别的文件的内容“插入”在 include 所在的位置,所以位置决定覆盖关系:全局文件里 [user] name 之后 [include] path = extra.conf,再下面又有 [user] email。结果 user.name 依次是 system、global、extra.conf(include 进来的)、local;user.email 依次来自 extra.conf(inc@example.com)和 global 里 include 之后的那一行(后读的生效)。includeIf \"gitdir:…/l69w*/\" 只在仓库路径匹配时才引入:路径不匹配的 l69 得到 me@home.example,匹配的 l69work 得到工作身份和 me@corp.example——给公司目录配一套身份。", t=tl(S(4)), mark=lidx(S(4), 'extra.conf', 'l69work(匹配'), done=lidx(S(4), 'l69(路径不匹配)', 'includeIf "gitdir:"'), kv=KV([['include', '在这个位置插入另一个文件'], ['includeIf gitdir:', '路径匹配才引入'], ['位置', '后面的覆盖前面的']], ['includeIf gitdir:'])),
    step("多值的键会叠加:remote.origin.fetch 在 global 里一个值、local 里一个值,--show-scope --get-all 两个都列出(global 的 +refs/heads/global/*… 和 local 的 +refs/heads/*:refs/remotes/origin/*),--get 取最后一个。写操作默认只改 local 文件:git config --unset remote.origin.fetch 之后只删掉 local 的那一个,global 的那个仍在。所以全局层的多值键会和仓库层的一起生效,不是被覆盖。", t=tl(S(5)), mark=lidx(S(5), 'global\t+refs/heads/global', 'local\t+refs/heads/*'), done=lidx(S(5), '$ git config --get remote.origin.fetch', 'git config --unset remote.origin.fetch'), kv=KV([['单值键', '后面覆盖前面'], ['多值键', '叠加,--get-all 全部列出'], ['--get', '取最后一个'], ['写操作', '默认只改 local']], ['多值键'])),
    step("global 层的读取:只有 $XDG_CONFIG_HOME/git/config(没有 ~/.gitconfig)时它被读为 global(core.pager=xdg-pager、core.editor=xdg-editor);两个文件都存在时都读,XDG 的在前、~/.gitconfig 在后,所以 ~/.gitconfig 的 core.pager=home-pager 覆盖前者。git config --global 写入的是 ~/.gitconfig(已存在时优先),不是 XDG 那个(True / False)。", t=tl(S(6)), mark=lidx(S(6), '两个都有', 'home-pager'), done=lidx(S(6), '只有 $XDG_CONFIG_HOME', 'xdg-pager', '写入的是 ~/.gitconfig'), kv=KV([['XDG', '$XDG_CONFIG_HOME/git/config,先读'], ['~/.gitconfig', '后读,覆盖 XDG'], ['--global 写入', '~/.gitconfig 存在则写它']], ['~/.gitconfig'])),
]
A = mkarti('l69', 69, 'Git,config,优先级,include,includeIf,真实验证,动画演示',
    '实测 git 配置的层级与优先级:system → global → local 后读的覆盖先读的;worktree 层(extensions.worktreeConfig)在 local 之后;-c 与 GIT_CONFIG_COUNT 环境变量更高;include 按位置插入,includeIf gitdir: 可按路径引入不同身份;多值键(如 remote.origin.fetch)叠加,--get 取最后一个,写操作默认只改 local;XDG 与 ~/.gitconfig 同时存在时都读。',
    'user.name 在好几个地方都设了,到底哪个生效?include 和 includeIf 怎么用?多值的键怎么叠加?worktree 级别的配置是什么?这篇用 --show-origin --show-scope 把每个值的来源和顺序都列出来。',
    [('后读覆盖先读', 'system → global → local → worktree → -c/环境变量,生效值总是最后一个'), ('includeIf gitdir:', '路径匹配才引入的配置,常用来给公司和个人目录配不同的 user.email'), ('多值叠加', 'remote.origin.fetch 这类多值键在各层累加,而不是被覆盖')],
    [('层级', '<p>git 依次读 system、global(<code>~/.gitconfig</code> 与 XDG)、local(<code>.git/config</code>)、worktree(<code>config.worktree</code>),再是环境变量与命令行 <code>-c</code>。同名的单值键,后读的覆盖先读的;<code>--show-origin --show-scope</code> 显示每个值的来源。</p>'),
     ('命令行与环境', '<p><code>git -c k=v</code> 和 <code>GIT_CONFIG_COUNT/KEY_n/VALUE_n</code> 都属于 command 层,在所有文件之后读,命令行最后。</p>'),
     ('worktree 层', '<p>设置 <code>extensions.worktreeConfig=true</code> 后,<code>git config --worktree</code> 把值写进该工作树自己的 <code>config.worktree</code>,优先级高于 local,其它工作树看不到。</p>'),
     ('include', '<p><code>[include] path</code> 把另一个文件的内容插入到那个位置,所以位置决定覆盖关系;<code>[includeIf "gitdir:…"]</code> 仅当仓库路径匹配时才引入,适合按目录切换身份。</p>'),
     ('多值键', '<p>多值的键(如 <code>remote.origin.fetch</code>)在各层累加;<code>--get-all</code> 全部列出,<code>--get</code> 取最后一个。写操作默认只改 local 文件。</p>'),
     ('global 的两个位置', '<p><code>$XDG_CONFIG_HOME/git/config</code> 和 <code>~/.gitconfig</code> 都被读,后者在后;<code>git config --global</code> 写入已存在的 <code>~/.gitconfig</code>。</p>')],
    steps,
    [ENV_I_GIT + '。为了不读真实的系统和用户配置,实验用 GIT_CONFIG_SYSTEM、GIT_CONFIG_GLOBAL 指向实验专用的文件(第六节改用 HOME 和 XDG_CONFIG_HOME 指到实验目录);路径在输出里简化',
     '没有验证:真实的系统配置文件位置(/etc/gitconfig 或安装前缀下的 etc/gitconfig,这台机器没有 /etc/gitconfig);includeIf 的 onbranch:、hasconfig:remote.*.url: 条件;git config -f 指定文件;git config --blob;core.sshCommand 等具体配置项的含义;配置里的路径展开(~)'],
    '配置的优先级')
